// The recommendation-sorting 3.2 duty: the continue surface's scored default
// (score desc, ties by recency — NOT the collection listings' alphabetical
// floor), the sort=recent opt-out serving today's recency order unscored, the
// score-then-window page cut, and the single-item route carrying rec_score —
// all asserted over the REAL router wiring and a real store, the tag chain
// injected through the ModulePresentation seam exactly as cmd wires it.

// decodeProgressList decodes the progress listing wire shape.
func decodeProgressList(t *testing.T, resp *http.Response) progressListResponse {
	t.Helper()
	var lr progressListResponse
	if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
		t.Fatalf("decode progressListResponse: %v", err)
	}
	return lr
}

// progressWireScore re-marshals one row and reports whether rec_score is on
// the wire (the omitempty observability probe, as in the collection tests).
func progressWireScore(t *testing.T, d progressDTO) (float64, bool) {
	t.Helper()
	b, err := json.Marshal(d)
	if err != nil {
		t.Fatalf("remarshal %s: %v", d.ItemID, err)
	}
	var wire map[string]any
	if err := json.Unmarshal(b, &wire); err != nil {
		t.Fatalf("unmarshal %s: %v", d.ItemID, err)
	}
	v, has := wire["rec_score"]
	if !has {
		return 0, false
	}
	f, ok := v.(float64)
	if !ok {
		t.Fatalf("rec_score for %s is %T, want a number", d.ItemID, v)
	}
	return f, true
}

// TestListProgressRecScore covers the scored default on the continue surface:
// every listed row carries the resume bonus (the row IS a positive progress
// fact), tags ride the item's genres (episodes join the SERIES document), the
// recency tiebreak orders equal scores newest-first, unwatched and
// zero-position items never surface, and the page cut lands AFTER the score
// order (score-then-window).
func TestListProgressRecScore(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	// Films: the tagged one (own-document genres, weighted), and two plain
	// ones written at different times so the recency tiebreak at the 1000
	// tier is observable (filmPlain newer than filmOld).
	filmTagged := seedRecsItem(t, st, lib, "itm_pf", "pf.mkv", map[string]any{
		"sources": map[string]any{recsMetaNS: map[string]any{"description": "d", "genres": []string{"action"}}},
	}, time.Time{})
	filmOld := seedRecsItem(t, st, lib, "itm_po", "po.mkv", map[string]any{}, time.Time{})
	filmPlain := seedRecsItem(t, st, lib, "itm_pp", "pp.mkv", map[string]any{}, time.Time{})
	if err := st.ApplyTagWeights(ctx, []string{"action"}, time.Now().UTC()); err != nil {
		t.Fatalf("ApplyTagWeights: %v", err)
	}
	// A started serial: the episode with progress scores 1000 + the drama
	// weight joined from the SERIES document (the episode document carries
	// nothing); its fresh unwatched sibling has NO progress row and must stay
	// absent from the list.
	seedRecsSeries(t, st, lib, "show", recsSeriesDoc("Show", "drama"))
	epStarted := seedRecsItem(t, st, lib, "itm_e1", "show/e1.mkv", recsEpisodeDoc("show", ""), time.Time{})
	epFresh := seedRecsItem(t, st, lib, "itm_e2", "show/e2.mkv", recsEpisodeDoc("show", ""), time.Time{})
	// A stored zero position (a valid "back to start") is not a continue
	// candidate: absent from the list.
	filmZero := seedRecsItem(t, st, lib, "itm_pz", "pz.mkv", map[string]any{}, time.Time{})

	// Write order old → new, strictly later stamps per write.
	for _, p := range []struct {
		id  string
		pos int64
	}{
		{filmOld.ID, 100},
		{epStarted.ID, 100},
		{filmPlain.ID, 100},
		{filmTagged.ID, 100},
		{filmZero.ID, 0},
	} {
		if _, err := st.PutProgress(ctx, p.id, p.pos); err != nil {
			t.Fatalf("PutProgress %s: %v", p.id, err)
		}
		time.Sleep(2 * time.Millisecond)
	}

	t.Run("scored_default_order_and_rec_score", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		lr := decodeProgressList(t, resp)
		// 1002 for the weighted film, 1001 for the episode (the joined drama
		// weight), then the 1000 tie ordered newest-first.
		wantIDs(t, servedIDs(lr.Items, func(d progressDTO) string { return d.ItemID }),
			filmTagged.ID, epStarted.ID, filmPlain.ID, filmOld.ID)
		wantScores := map[string]float64{
			filmTagged.ID: 1002, epStarted.ID: 1001, filmPlain.ID: 1000, filmOld.ID: 1000,
		}
		for _, d := range lr.Items {
			got, has := progressWireScore(t, d)
			if !has {
				t.Fatalf("scored row %s omitted rec_score", d.ItemID)
			}
			if want, ok := wantScores[d.ItemID]; ok && got != want {
				t.Fatalf("row %s rec_score = %v, want %v", d.ItemID, got, want)
			}
		}
	})

	t.Run("unwatched_and_zero_position_absent", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress", "", adminToken)
		defer resp.Body.Close()
		lr := decodeProgressList(t, resp)
		for _, d := range lr.Items {
			if d.ItemID == epFresh.ID {
				t.Fatalf("unwatched episode %s served — only positive-progress rows list", d.ItemID)
			}
			if d.ItemID == filmZero.ID {
				t.Fatalf("zero-position item %s served — not a continue candidate", d.ItemID)
			}
		}
	})

	t.Run("score_then_window", func(t *testing.T) {
		// D7: the page cut applies AFTER the score order — a limit=1 page is
		// the TOP-SCORING row, not the most recent.
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress?limit=1", "", adminToken)
		defer resp.Body.Close()
		lr := decodeProgressList(t, resp)
		wantIDs(t, servedIDs(lr.Items, func(d progressDTO) string { return d.ItemID }), filmTagged.ID)

		resp = doRequest(t, h, http.MethodGet, "/api/v1/progress?limit=2", "", adminToken)
		defer resp.Body.Close()
		lr = decodeProgressList(t, resp)
		wantIDs(t, servedIDs(lr.Items, func(d progressDTO) string { return d.ItemID }), filmTagged.ID, epStarted.ID)
	})
}

// TestListProgressSortRecent covers the opt-out: sort=recent restores the
// store's pure recency order byte-for-byte, unscored (rec_score kept off the
// wire by omitempty), and an unknown sort value is 400 — the collection
// listings' parse posture.
func TestListProgressSortRecent(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	// Insertion order a → b → c; b carries the weighted tag so the scored
	// default inverts exactly this order.
	a := seedRecsItem(t, st, lib, "itm_ra", "ra.mkv", map[string]any{}, time.Time{})
	tagged := seedRecsItem(t, st, lib, "itm_rb", "rb.mkv", map[string]any{
		"sources": map[string]any{recsMetaNS: map[string]any{"description": "d", "genres": []string{"action"}}},
	}, time.Time{})
	c := seedRecsItem(t, st, lib, "itm_rc", "rc.mkv", map[string]any{}, time.Time{})
	if err := st.ApplyTagWeights(ctx, []string{"action"}, time.Now().UTC()); err != nil {
		t.Fatalf("ApplyTagWeights: %v", err)
	}
	for _, id := range []string{a.ID, tagged.ID, c.ID} {
		if _, err := st.PutProgress(ctx, id, 100); err != nil {
			t.Fatalf("PutProgress %s: %v", id, err)
		}
		time.Sleep(2 * time.Millisecond)
	}

	t.Run("default_inverts_to_score_order", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress", "", adminToken)
		defer resp.Body.Close()
		lr := decodeProgressList(t, resp)
		wantIDs(t, servedIDs(lr.Items, func(d progressDTO) string { return d.ItemID }), tagged.ID, c.ID, a.ID)
	})

	t.Run("sort_recent_restores_recency_unscored", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress?sort=recent", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		lr := decodeProgressList(t, resp)
		wantIDs(t, servedIDs(lr.Items, func(d progressDTO) string { return d.ItemID }), c.ID, tagged.ID, a.ID)
		for _, d := range lr.Items {
			if _, has := progressWireScore(t, d); has {
				t.Fatalf("sort=recent computed scores (%s on the wire) — the opt-out must serve unscored", d.ItemID)
			}
		}
	})

	t.Run("unknown_sort_is_400", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress?sort=path", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want 400", resp.StatusCode)
		}
	})
}

// TestGetProgressRecScore covers the single-item route's additive score: a
// positive record carries the resume bonus over the joined tags; a stored
// zero position scores on tags alone (not a continue candidate — the
// InProgress fact is the positive row); the shape stays the one progressDTO.
func TestGetProgressRecScore(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	watched := seedRecsItem(t, st, lib, "itm_g1", "g1.mkv", map[string]any{
		"sources": map[string]any{recsMetaNS: map[string]any{"description": "d", "genres": []string{"action"}}},
	}, time.Time{})
	if err := st.ApplyTagWeights(ctx, []string{"action"}, time.Now().UTC()); err != nil {
		t.Fatalf("ApplyTagWeights: %v", err)
	}
	// A stored zero position with an unweighted genre: score = the weight
	// (1) — no resume bonus.
	zero := seedRecsItem(t, st, lib, "itm_g0", "g0.mkv", map[string]any{
		"sources": map[string]any{recsMetaNS: map[string]any{"description": "d", "genres": []string{"drama"}}},
	}, time.Time{})
	// An episode whose genres join the SERIES document.
	seedRecsSeries(t, st, lib, "serial", recsSeriesDoc("Serial", "thriller"))
	ep := seedRecsItem(t, st, lib, "itm_ge", "serial/e1.mkv", recsEpisodeDoc("serial", ""), time.Time{})

	if _, err := st.PutProgress(ctx, watched.ID, 500); err != nil {
		t.Fatalf("PutProgress watched: %v", err)
	}
	if _, err := st.PutProgress(ctx, zero.ID, 0); err != nil {
		t.Fatalf("PutProgress zero: %v", err)
	}
	if _, err := st.PutProgress(ctx, ep.ID, 60); err != nil {
		t.Fatalf("PutProgress ep: %v", err)
	}

	get := func(t *testing.T, id string) progressDTO {
		t.Helper()
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress/"+id, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		var pr progressDTO
		if err := json.NewDecoder(resp.Body).Decode(&pr); err != nil {
			t.Fatalf("decode progressDTO: %v", err)
		}
		return pr
	}

	t.Run("positive_record_carries_resume_bonus", func(t *testing.T) {
		pr := get(t, watched.ID)
		got, has := progressWireScore(t, pr)
		if !has || got != 1002 {
			t.Fatalf("rec_score = (%v, %v), want 1002 on the wire", got, has)
		}
	})

	t.Run("zero_position_scores_tags_alone", func(t *testing.T) {
		pr := get(t, zero.ID)
		got, has := progressWireScore(t, pr)
		if !has || got != 1 {
			t.Fatalf("rec_score = (%v, %v), want 1 (drama weight, no resume bonus)", got, has)
		}
	})

	t.Run("episode_joins_series_genres", func(t *testing.T) {
		pr := get(t, ep.ID)
		got, has := progressWireScore(t, pr)
		if !has || got != 1001 {
			t.Fatalf("rec_score = (%v, %v), want 1001 (resume + thriller weight from the series document)", got, has)
		}
	})
}

// TestGetProgressRecScoreZeroPositionEpisodeStartedSeries pins the GATE 2
// reviewer finding on the single-item route's scored composition: an episode
// of a STARTED series whose OWN stored progress row sits at position ZERO (a
// valid "back to start", excluded from the positive-progress facts) must
// serve the new-episode bonus (500 + the joined series-genre weight, within
// the new-episode window) — the SAME score the items grid serves for the
// entity — NOT the tags-only score a one-item startedness derivation yields.
// Both startedness legs are pinned (the spec's started-series definition):
// a sibling episode carrying a positive progress row, and one carrying only
// a watched-ledger row.
func TestGetProgressRecScoreZeroPositionEpisodeStartedSeries(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	// Two started series, one per startedness leg, both carrying the drama
	// genre (weight 1) on the SERIES document the episodes join.
	seedRecsSeries(t, st, lib, "prog-show", recsSeriesDoc("ProgShow", "drama"))
	seedRecsSeries(t, st, lib, "watched-show", recsSeriesDoc("WatchedShow", "drama"))
	// The startedness carriers: a positive-progress sibling and a
	// watched-ledger-only sibling.
	epProgSibling := seedRecsItem(t, st, lib, "itm_zp1", "prog-show/e1.mkv", recsEpisodeDoc("prog-show", ""), time.Time{})
	epWatchedSibling := seedRecsItem(t, st, lib, "itm_zw1", "watched-show/e1.mkv", recsEpisodeDoc("watched-show", ""), time.Time{})
	// The targets under test: fresh episodes whose OWN rows sit at position
	// ZERO — the write is valid (recs_ordering.go's zero-position contract)
	// but never lands in the positive-progress facts.
	epProgTarget := seedRecsItem(t, st, lib, "itm_zp2", "prog-show/e2.mkv", recsEpisodeDoc("prog-show", ""), time.Time{})
	epWatchedTarget := seedRecsItem(t, st, lib, "itm_zw2", "watched-show/e2.mkv", recsEpisodeDoc("watched-show", ""), time.Time{})
	if err := st.ApplyTagWeights(ctx, []string{"drama"}, time.Now().UTC()); err != nil {
		t.Fatalf("ApplyTagWeights: %v", err)
	}
	if _, err := st.PutProgress(ctx, epProgSibling.ID, 100); err != nil {
		t.Fatalf("PutProgress prog sibling: %v", err)
	}
	if _, err := st.PutProgress(ctx, epProgTarget.ID, 0); err != nil {
		t.Fatalf("PutProgress prog target: %v", err)
	}
	if err := st.InsertWatched(ctx, epWatchedSibling.ID, lib, "watched-show", time.Now().UTC()); err != nil {
		t.Fatalf("InsertWatched watched sibling: %v", err)
	}
	if _, err := st.PutProgress(ctx, epWatchedTarget.ID, 0); err != nil {
		t.Fatalf("PutProgress watched target: %v", err)
	}

	get := func(t *testing.T, id string) float64 {
		t.Helper()
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress/"+id, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		var pr progressDTO
		if err := json.NewDecoder(resp.Body).Decode(&pr); err != nil {
			t.Fatalf("decode progressDTO: %v", err)
		}
		got, has := progressWireScore(t, pr)
		if !has {
			t.Fatalf("rec_score omitted for %s — the scored route must carry it", id)
		}
		return got
	}

	for _, tc := range []struct {
		name string
		id   string
	}{
		{"progress_started_sibling", epProgTarget.ID},
		{"watched_started_sibling", epWatchedTarget.ID},
	} {
		t.Run(tc.name, func(t *testing.T) {
			// 500 (the new-episode bonus, the target is fresh within the
			// window) + 2 (the tag component: base 1 + the drama weight
			// joined from the series document — recs.Score's 1+weight rule).
			// The pre-fix composition served 2 (tags-only): its ONE-item
			// slice derived startedness solely from the target's own facts.
			if got := get(t, tc.id); got != 502 {
				t.Fatalf("rec_score = %v, want 502 (new-episode bonus + tag component; series started by the sibling)", got)
			}
		})
	}
}
